import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const c=JSON.parse('{"title":"Item Quality / Masterworks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/items/item-quality.md","filePath":"guide/items/item-quality.md"}'),o={name:"guide/items/item-quality.md"};function s(n,e,l,d,m,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="item-quality-masterworks" tabindex="-1">Item Quality / Masterworks <a class="header-anchor" href="#item-quality-masterworks" aria-label="Permalink to &quot;Item Quality / Masterworks&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html">full design specification</a>.</p><h2 id="quality-means-doing-a-job-well" tabindex="-1">Quality means doing a job well <a class="header-anchor" href="#quality-means-doing-a-job-well" aria-label="Permalink to &quot;Quality means doing a job well&quot;">​</a></h2><p>A good weapon should handle better, behave more consistently and keep its useful performance longer—not simply display a larger damage number. Weapon identity still matters: a better dagger should not become a better blunt-trauma weapon than a war hammer.</p><p>The same proposed quality language should apply to crafted equipment and PvM drops. Crafting should remain a worthwhile endgame source.</p><h2 id="the-proposed-categories" tabindex="-1">The proposed categories <a class="header-anchor" href="#the-proposed-categories" aria-label="Permalink to &quot;The proposed categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>What it means</th></tr></thead><tbody><tr><td>Crude</td><td>Usable but clearly deficient</td></tr><tr><td>Common</td><td>Competent everyday equipment</td></tr><tr><td>Fine</td><td>Noticeably above average</td></tr><tr><td>Exceptional</td><td>High-quality professional work</td></tr><tr><td>Superior</td><td>Expert work that stands out</td></tr><tr><td>Masterwork</td><td>An extremely rare technical masterpiece</td></tr><tr><td>Singular / Relic</td><td>Nearly unique history or behavior, not simply the next numeric tier</td></tr></tbody></table><p>Skill, learned techniques, materials and execution set the possible result. Luck plays only a small role. Higher skill broadens possibilities, but the categories are not guaranteed skill unlocks, and skill 100 should not make Masterworks routine.</p><h2 id="what-you-might-notice" tabindex="-1">What you might notice <a class="header-anchor" href="#what-you-might-notice" aria-label="Permalink to &quot;What you might notice&quot;">​</a></h2><p>Compared with a Common longsword, an Exceptional one could have better balance, more consistent cutting/thrust performance, stronger construction and an edge that lasts longer. Common equipment must remain useful; Exceptional is not shorthand for a fixed damage bonus.</p><h2 id="special-properties-and-memorable-items" tabindex="-1">Special properties and memorable items <a class="header-anchor" href="#special-properties-and-memorable-items" aria-label="Permalink to &quot;Special properties and memorable items&quot;">​</a></h2><p>A Masterwork is not automatically magical. Rare high-end objects may have justified traits or a latent resonance that awakens through unusual use, a place, a creature or a ritual. A Frostwood bow awakening after a cold-related event is an illustration, not a guaranteed recipe or quest.</p><p>Properties should create tactical choices and specialization, with tradeoffs and counterplay. Ordinary excellent equipment should stay competitive. Sacred/Resonant Sets are a future proposal for rare compatible items; they do not grant protection from death or loot loss.</p><h2 id="related-systems" tabindex="-1">Related systems <a class="header-anchor" href="#related-systems" aria-label="Permalink to &quot;Related systems&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/professions/overview.html">Professions</a> explains learning, production and reputation. <a href="/Syrolands-Public/guide/professions/blacksmithing.html">Blacksmithing</a> and <a href="/Syrolands-Public/guide/professions/carpentry.html">Carpentry / Bowmaking</a> show craft paths. Exact quality ranges, traits, awakening conditions and combat effects remain unresolved in the <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html">full specification</a>.</p>',15)])])}const p=t(o,[["render",s]]);export{c as __pageData,p as default};
